-- ESA ESL Linear Series RL Circuit Step Transient
MODEL RLCircuit
  CONSTANT REAL: R = 12.0;      -- Resistance (Ohm)
  CONSTANT REAL: L = 0.08;      -- Inductance (H)
  CONSTANT REAL: VIN = 24.0;    -- Step supply voltage (V)
  REAL: i_curr, v_ind, power_r;
INITIAL
  i_curr = 0.0;
DYNAMIC
  i_curr' = (VIN - R * i_curr) / L;
  v_ind = VIN - R * i_curr;
  power_r = R * i_curr ** 2;
TERMINAL
  v_ind = 0.0;
END MODEL RLCircuit

-- ESA ESL Hybrid Bouncing Ball with Coefficient of Restitution
MODEL BouncingBall
  CONSTANT REAL: g = 9.80665;   -- Gravitational acceleration (m/s^2)
  CONSTANT REAL: e = 0.82;      -- Coefficient of restitution
  REAL: y, v;
  INTEGER: bounces = 0;
INITIAL
  y = 5.0;
  v = 0.0;
DYNAMIC
  y' = v;
  v' = -g;
  WHEN y <= 0.0 AND v < 0.0 THEN
    v := -e * v;
    y := 0.0;
    bounces := bounces + 1;
  END_WHEN
END MODEL BouncingBall

-- ESA ESL LEO Satellite Solar Array Eclipse & Battery SOC Cycling
STUDY LeoPowerStudy
  PACKAGE OrbitParams
    CONSTANT REAL: P_SOLAR = 480.0;  -- Illuminated solar array power (W)
    CONSTANT REAL: P_LOAD = 260.0;   -- Nominal bus payload power (W)
    CONSTANT REAL: E_CAP = 360000.0; -- Battery energy capacity (J)
    CONSTANT REAL: ETA_CHG = 0.92;   -- Charge efficiency
    CONSTANT REAL: OMEGA_O = 0.0011; -- Orbital angular rate (rad/s)
  END PACKAGE OrbitParams

  MODEL PowerBus
    CONSTANT REAL: P_SOLAR = 480.0;
    CONSTANT REAL: P_LOAD = 260.0;
    CONSTANT REAL: E_CAP = 360000.0;
    CONSTANT REAL: ETA_CHG = 0.92;
    CONSTANT REAL: OMEGA_O = 0.0011;
    REAL: phase, soc, p_net, sunlit;
  INITIAL
    phase = 0.0;
    soc = 0.85;
    sunlit = 1.0;
  DYNAMIC
    phase' = OMEGA_O;
    IF sunlit > 0.5 THEN
      p_net = ETA_CHG * (P_SOLAR - P_LOAD);
    ELSE
      p_net = -P_LOAD;
    END_IF
    soc' = p_net / E_CAP;
    WHEN phase >= 3.8 THEN
      sunlit := 0.0;
    END_WHEN
    WHEN phase >= 6.28318 THEN
      phase := 0.0;
      sunlit := 1.0;
    END_WHEN
  END MODEL PowerBus
END STUDY LeoPowerStudy

-- ESA ESL Modular Electro-Hydraulic Flight Control Actuator Study
STUDY ElectroHydraulicStudy
  PACKAGE HydraulicConstants
    CONSTANT REAL: P_SUPPLY = 21.0e6; -- Supply pressure (Pa)
    CONSTANT REAL: BETA_OIL = 1.4e9;  -- Hydraulic bulk modulus (Pa)
    CONSTANT REAL: A_PISTON = 0.002;  -- Piston area (m^2)
    CONSTANT REAL: V_CHAMBER = 0.0008;-- Effective chamber volume (m^3)
  END PACKAGE HydraulicConstants

  SUBMODEL ServoValve(IN REAL: cmd; IN REAL: kv; OUT REAL: q_flow)
  DYNAMIC
    q_flow = kv * cmd;
  END SUBMODEL ServoValve

  MODEL ActuatorSystem
    CONSTANT REAL: KV = 0.0018;
    CONSTANT REAL: KP = 14.0;
    CONSTANT REAL: KD = 0.35;
    CONSTANT REAL: BETA_OIL = 1.4e9;
    CONSTANT REAL: A_PISTON = 0.002;
    CONSTANT REAL: V_CHAMBER = 0.0008;
    CONSTANT REAL: MASS = 12.0;
    CONSTANT REAL: DAMP = 65.0;
    CONSTANT REAL: X_REF = 0.05;
    REAL: x_pos, v_pos, delta_p, cmd, q_flow;
  INITIAL
    x_pos = 0.0;
    v_pos = 0.0;
    delta_p = 0.0;
  DYNAMIC
    cmd = KP * (X_REF - x_pos) - KD * v_pos;
    ServoValve(cmd, KV, q_flow);
    delta_p' = (BETA_OIL / V_CHAMBER) * (q_flow - A_PISTON * v_pos);
    x_pos' = v_pos;
    v_pos' = (A_PISTON * delta_p - DAMP * v_pos) / MASS;
    WHEN x_pos >= 0.095 THEN
      x_pos := 0.095;
      v_pos := 0.0;
    END_WHEN
  END MODEL ActuatorSystem
END STUDY ElectroHydraulicStudy

